"""Experiment exp09: average the answers of several stackers (v7's, exp08 L/LC, exp07 RS).

    python external/exp09.py            # writes experiments/exp09_blend/results.md and results.json
    python external/exp09.py --final    # trains the missing stackers on all 7 DFL matches -> model/params_v9.json

Everything comes from checkpoints (exp06_TW, exp07_RS, exp08_L, exp08_LC folds and holdout): the
per-frame probabilities are averaged, the decoder is searched again, all judged on DFL truth
rewritten to controlled possession. Rule fixed in experiments/exp09_blend/README.md.
"""

import datetime
import json
import os
import sys
import time

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, HERE)

import exp07  # noqa: E402
import exp03  # noqa: E402
import exp05  # noqa: E402

MIN_GAIN = 0.005
VARIANTS = {"E2": ("exp06_TW", "exp08_L"), "E4": ("exp06_TW", "exp08_L", "exp08_LC", "exp07_RS")}
OUT_DIR = os.path.join(ROOT, "experiments", "exp09_blend")


def cases(source, part):
    """{scenario: [(prob, change, half, controlled truth, rest)]} of one stacker for a fold or the holdout."""
    done = exp05.load("{}_{}".format(source, part))
    return {s: [(p, c, h, exp07.controlled(g), r) for p, c, h, g, r in done[s]] for s in exp03.DEGRADED}


def blend(sources, part):
    parts = [cases(src, part) for src in sources]
    out = {}
    for s in exp03.DEGRADED:
        out[s] = []
        for group in zip(*[p[s] for p in parts]):
            first = group[0]
            for other in group[1:]:
                assert other[0].shape == first[0].shape and np.array_equal(other[3], first[3]), "cases not aligned"
            out[s].append((np.mean([g[0] for g in group], axis=0),) + tuple(first[1:]))
    return out


def block(by_scenario, decoder):
    s = {sc: exp03.summary(by_scenario[sc], decoder) for sc in exp03.DEGRADED}
    return s, float(np.mean([s[sc]["spellF1"] for sc in exp03.MATCHED])), float(min(s[sc]["spellF1"] for sc in exp03.DEGRADED))


def main():
    started = time.time()
    with open(os.path.join(exp07.OUT_DIR, "results.json"), encoding="utf-8") as handle:
        r6 = json.load(handle)["results"]["R6"]
    results = {}
    for v, sources in VARIANTS.items():
        print("variant", v, flush=True)
        cv_cases = {s: [] for s in exp03.DEGRADED}
        for held in exp03.TUNE:
            done = blend(sources, "fold_" + held)
            for s in exp03.DEGRADED:
                cv_cases[s] += done[s]
        decoder = exp03.search(cv_cases[exp03.MATCHED[0]] + cv_cases[exp03.MATCHED[1]], True)
        cv, cv_matched, cv_worst = block(cv_cases, decoder)
        holdout, holdout_matched, _ = block(blend(sources, "holdout"), decoder)
        results[v] = {"sources": sources, "decoder": decoder, "cv": cv, "holdout": holdout,
                      "cv_matched": cv_matched, "cv_worst": cv_worst, "holdout_matched": holdout_matched}
        print("  {} CV matched {:.4f} worst {:.4f} holdout {:.4f} ({:.0f} min)".format(
            v, cv_matched, cv_worst, holdout_matched, (time.time() - started) / 60), flush=True)
    best = max(results, key=lambda v: results[v]["cv_matched"])
    adopt = (results[best]["cv_matched"] >= r6["cv_matched"] + MIN_GAIN
             and results[best]["cv_worst"] >= r6["cv_worst"] - MIN_GAIN)
    out = {"best": best, "adopt": adopt, "results": results,
           "v7": {k: r6[k] for k in ("cv_matched", "cv_worst", "holdout_matched", "decoder")},
           "minutes": round((time.time() - started) / 60, 1),
           "written": datetime.datetime.now().replace(microsecond=0).isoformat()}
    with open(os.path.join(OUT_DIR, "results.json"), "w", encoding="utf-8") as handle:
        json.dump(out, handle, indent=1, default=float)
    lines = ["# exp09 -- averaged stackers (generated by external/exp09.py)", "",
             "Rule -> **{}**".format("adopt " + best if adopt else "keep v7"), "",
             "| | CV matched | CV worst | holdout matched | decoder |", "|---|---|---|---|---|",
             "| v7 | {:.4f} | {:.4f} | {:.3f} | {} |".format(r6["cv_matched"], r6["cv_worst"], r6["holdout_matched"], r6["decoder"])]
    for v, r in results.items():
        lines.append("| {} | {:.4f} | {:.4f} | {:.3f} | {} |".format(v, r["cv_matched"], r["cv_worst"], r["holdout_matched"], r["decoder"]))
    with open(os.path.join(OUT_DIR, "results.md"), "w", encoding="utf-8") as handle:
        handle.write("\n".join(lines) + "\n")
    print("\n".join(lines), flush=True)


def save(model, name):
    path = os.path.join(ROOT, "model", name)
    model.save_model(path + ".tmp")
    os.replace(path + ".tmp", path)
    return "model/" + name


def final():
    """The four members on all 7 DFL matches. v7's stacker (v6_stack) and L (v8_stack) exist already;
    LC = long-context stacker on rewritten truth over v4w's leave-one-out answers (exp06's);
    RS = frame + change + stacker all learnt on the rewritten truth (exp07's recipe)."""
    import exp06
    with open(os.path.join(OUT_DIR, "results.json"), encoding="utf-8") as handle:
        out = json.load(handle)
    if not out["adopt"] or out["best"] != "E4":
        print("nothing to write")
        return
    names = exp03.names_for("v3")
    matches = exp03.all_matches()[:7]
    with open(os.path.join(ROOT, "model", "params_v7.json"), encoding="utf-8") as handle:
        params = json.load(handle)
    v4w = {"frame_model": params["frame_model"], "change_model": params["change_model"]}
    if not os.path.isfile(os.path.join(ROOT, "model", "v8_stack.txt")):
        raise SystemExit("run external/exp08.py --final --force first (L stacker)")
    # LC
    exp03.item, exp06.LONG = exp07.item, True
    answers = {}
    for m in matches:
        answers.update(exp05.load("exp06_final_loo_" + m))
    lc = save(exp06.stack_fit(answers, names, exp07.STACK_ALPHA), "v9_lc_stack.txt")
    print("LC stacker written", flush=True)
    # RS
    exp06.LONG = False
    frame_model, change_model = exp07.train(matches, names)
    rs = {"frame_model": save(frame_model, "v9_rs_frame.txt"), "change_model": save(change_model, "v9_rs_change.txt")}
    print("RS first stage written", flush=True)
    got = {}
    for m in matches:
        got.update(exp07.checkpoint("final_loo_" + m, lambda: exp06.first_stage([x for x in matches if x != m], [m], names)))
        print("  leave-one-out", m, flush=True)
    rs["stack_model"] = save(exp06.stack_fit(got, names, exp07.STACK_ALPHA), "v9_rs_stack.txt")
    params.update({
        "variant": params["variant"] + "; exp09 E4 (mean of four stackers)",
        "blend": [dict(v4w, stack_model="model/v6_stack.txt"),
                  dict(v4w, stack_model="model/v8_stack.txt", stack_long=True),
                  dict(v4w, stack_model=lc, stack_long=True),
                  rs],
        "decoder": out["results"]["E4"]["decoder"],
        "decoder_tuned_on": "exp09: mean of the four stackers' leave-one-out answers on the TUNE matches, judged on controlled possession",
        "written": datetime.datetime.now().replace(microsecond=0).isoformat()})
    with open(os.path.join(ROOT, "model", "params_v9.json"), "w", encoding="utf-8") as handle:
        json.dump(params, handle, indent=1)
    print("written model/params_v9.json", flush=True)


if __name__ == "__main__":
    final() if "--final" in sys.argv else main()
